import SearchableSelect from '../../../../../CORE/Resources/js/Components/SearchableSelect.vue';
const props = defineProps<{ partner:any; groupOptions:any[]; priceListOptions:any[]; userOptions:any[] }>();
const form = useForm({
  type: props.partner.type, name: props.partner.name, legal_name: props.partner.legal_name ?? '', partner_code: props.partner.partner_code, group_id: props.partner.group_id, price_list_id: props.partner.price_list_id,
  trade_license: props.partner.trade_license ?? '', tin: props.partner.tin ?? '', bin: props.partner.bin ?? '', vat_reg_no: props.partner.vat_reg_no ?? '', nid: props.partner.nid ?? '',
