function addBank(){ form.banks.push({ bank_name:'', branch:'', account_name:'', account_no:'', routing_no:'', swift_code:'', is_primary:false }); }
function removeBank(i:number){ form.banks.splice(i,1); }
function submit(){ form.put(route('partner.customers.update', props.partner.id)); }
